import{_ as a,o,c as n,aw as l}from"./chunks/framework.DLufY-ao.js";const y=JSON.parse('{"title":"Декораторы","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common/typescript/class/decorators.md","filePath":"wiki/dev-commit/common/typescript/class/decorators.md"}'),e={name:"wiki/dev-commit/common/typescript/class/decorators.md"};function t(p,s,r,c,i,u){return o(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="декораторы" tabindex="-1">Декораторы <a class="header-anchor" href="#декораторы" aria-label="Permalink to &quot;Декораторы&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li><strong>Декораторы</strong> - являются инструментом декларативного программирования, они позволяют добавить к классам и их членам метаданные и тем самым изменить их поведение без изменения их кода</li><li>Декораторы представляют функции</li><li>Декораторы используют форму @expression, т.е. при использовании ставится символ @ перед именем декоратора. Хотя по сути expression может быть любая функция. Эта функция будет вызвана в процессе выполнения программы, причем вызывающий код добавит аргументы с информацией о том объекте, который был задекорирован.</li><li>Важно, что декоратор - это лишь функция. При использовании, среда исполнения сначала вызовет функцию-декоратор, и только потом будет выполнен основной сценарий объекта (если код декоратора содержит этот вызов). При наличии нескольких декораторов, они будет вызваны по очереди, сверху вниз.</li><li>Декоратор для функции, свойства или параметра функции можно применить только внутри некоего класса. В настоящее время компилятор Typescript не позволит применить декоратор для функции, которая написана вне класса.</li></ul><p>К каким элементам можно добавить декораторы:</p><ul><li>Классы</li><li>Методы</li><li>Методы доступа (Геттеры и Сеттеры)</li><li>Свойства</li><li>Параметры</li></ul><h2 id="установка-и-настроика" tabindex="-1">Установка и настройка <a class="header-anchor" href="#установка-и-настроика" aria-label="Permalink to &quot;Установка и настройка&quot;">​</a></h2><ul><li>Декораторы являются экпериментальной функциональностью языка TypeScript (на 2021 год), поэтому при компиляции следует указывать параметр experimentalDecorators в файле tsconfig.json</li></ul><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">{</span></span>
<span class="line"><span style="color:#E45649;">  &quot;compilerOptions&quot;</span><span style="color:#383A42;">: {</span></span>
<span class="line"><span style="color:#E45649;">    &quot;module&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;commonjs&quot;</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;declaration&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;removeComments&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;emitDecoratorMetadata&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;experimentalDecorators&quot;</span><span style="color:#383A42;">: </span><span style="color:#0184BC;">true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">    &quot;target&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;es2017&quot;</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#383A42;">  },</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><h2 id="использование" tabindex="-1">Использование <a class="header-anchor" href="#использование" aria-label="Permalink to &quot;Использование&quot;">​</a></h2>`,9)])])}const m=a(e,[["render",t]]);export{y as __pageData,m as default};
